          [[p1, p2], [p2, p1]].forEach(function (pr) { var s = pr[0], ot = pr[1]; if (s.row === k && ot.x > s.x) start = Math.max(start, s.x + Math.max(30, s.half + 7) + 0.42 * (ot.x - s.x) + 22); });
