            H("span", { class: "lx-ss-tick " + cls, html: (v == null ? "" : LX.icon(v ? "check" : "cross")) + LX.esc(k[1]),
              title: k[1] + ": " + (v == null ? "not sorted yet" : v ? "placed right" : "placed elsewhere") }, row);
