  function money(v) { var r = Math.round(v); return (r < 0 ? "−$" : "$") + Math.abs(r).toLocaleString("en-US"); }
  function millions(v, d) { d = d == null ? 1 : d; var x = v / 1e6, s = Math.abs(x).toFixed(d); return (x < 0 && +s !== 0 ? "−$" : "$") + s.replace(/\B(?=(\d{3})+(?!\d))/g, ",") + "M"; }
