        s0: { fuel: fuel0, res: sh.resistance, hp: sh.heatPump, dh: 0 }, pf: fuel0 > 0 ? sh.propane / fuel0 : 0,
        H: x.households, homeEq: x.households * Qd / x.heat.residentialMWh, rho: x.heat.residentialMWh / Qd, L: x.substationMW,
