    if (u === "$/kW" || u === "$/home") return function (v) { return "$" + kilo(v) + (u === "$/kW" ? "/kW" : " a home"); };
    if (u === "$/MWh") return function (v) { return "$" + kilo(v) + "/MWh"; };
