        y: { min: 0, max: Math.ceil(top / step) * step, step: step, fmt: function (v) { return kilo(v); }, unit: "MW" }, refs: refs, lines: lines,
        marks: [{ x: bi + 0.5, y: d.imp[bi], label: kilo(d.imp[bi]) + " MW at " + hh(bi), kind: "dot", pos: "above" }],
