        tip: function (x) { var h = Math.max(0, Math.min(23, Math.floor(x))); return "<div><b>" + hh(h) + "</b></div><div>Bought " + kilo(d.imp[h]) + " MW</div><div>Used " + kilo(load[h]) + " MW</div>" + (d.lim[h] > 0.5 ? "<div>Room worth $" + kilo(d.lim[h]) + " per MW a year</div>" : ""); },
