            var s0 = v("bs_" + r + "_" + d.key + tg, 0, Infinity, 0), hd = P.S[d.d].h / P.S[d.d].days, hn = P.S[d.n].h / P.S[d.n].days;   // 12 h
            var dayEnd = [[s0, 1], [ch[d.d], hd * eta], [dis[d.d], -hd]];
